import { Given, When, Then } from '@cucumber/cucumber';
import { expect } from '@playwright/test';
import { ScenarioContext } from '../../Framework/src/utils/ScenarioContext';
import { resolvePassword } from '../../Framework/src/utils/passwordResolver';
import { getSharedBrowser } from '../../Framework/src/helper/hooks';
import { getAuthenticatedPage } from '../../Framework/src/helper/auth-setup';

function resolveRowPassword(row: Record<string, unknown>, column: string): string {
  const key = row[column] as string | undefined;
  return key ? resolvePassword(key) : '';
}

// ==================== Navigation ====================

Given('the user is on the Login page', async function (this: ScenarioContext) {
  await this.loginPage.navigateToLogin();
});

Given('the user is not authenticated', async function (this: ScenarioContext) {
  // Fresh browser context per scenario (see hooks.ts Before) — no prior session exists.
  expect(this.context).toBeTruthy();
});

// ==================== Login ====================

// These 3 steps test the literal login form itself (AUTH's own subject matter), so they
// can't reuse the cached session — each one is a real interactive login. 28 AUTH scenarios
// reference Super Admin's email directly; running them all would mean 28 real login
// attempts in quick succession, which previously tripped the live backend's login-attempt
// throttle. Keep these skipped for Super Admin specifically until AUTH's own coverage is
// deliberately re-enabled (e.g. a smaller, deliberately-paced subset).
function isSuperAdminEmail(email: string | undefined): boolean {
  return Boolean(email?.toLowerCase().includes('superadmin'));
}

When('the user logs in with the credentials from the test data', async function (this: ScenarioContext) {
  const email = this.testData.Email as string;
  if (isSuperAdminEmail(email)) return 'skipped';
  const password = resolveRowPassword(this.testData, 'PasswordKey');
  await this.loginPage.login(email, password);
});

When('the user enters email {string} and password {string} and clicks "Sign In"', async function (
  this: ScenarioContext,
  email: string,
  password: string,
) {
  if (isSuperAdminEmail(email)) return 'skipped';
  await this.loginPage.login(email, password);
});

When('the user logs in with the registered email but an incorrect password', async function (this: ScenarioContext) {
  const email = this.testData.Email as string;
  if (isSuperAdminEmail(email)) return 'skipped';
  await this.loginPage.login(email, 'WrongPass123');
});

Then('the user should be redirected to the {string} dashboard', async function (this: ScenarioContext, _role: string) {
  await this.loginPage.assertDashboardLoaded();
});

Then('the user should remain on the Login page', async function (this: ScenarioContext) {
  await expect(this.page).toHaveURL(/\/login/);
});

Then('a generic authentication-failure message should be displayed', async function (this: ScenarioContext) {
  await this.loginPage.assertLoginErrorVisible();
});

Then('the authentication-failure message should be visible and positioned near the Sign In form', async function (this: ScenarioContext) {
  await this.loginPage.assertLoginErrorVisible();
  await expect(this.loginPage.signInButton).toBeVisible();
});

Then('a mandatory-field validation error should be displayed for the {string} field', async function (
  this: ScenarioContext,
  fieldName: string,
) {
  const field = fieldName === 'Email' ? this.loginPage.emailInput : this.loginPage.passwordInput;
  await this.loginPage.assertValidationErrorFor(field);
});

Then('a format-validation error should be displayed for the {string} field', async function (this: ScenarioContext, fieldName: string) {
  const field = fieldName === 'Email' ? this.loginPage.emailInput : this.loginPage.passwordInput;
  await this.loginPage.assertValidationErrorFor(field);
});

Then('the Password field should be masked by default', async function (this: ScenarioContext) {
  expect(await this.loginPage.isPasswordMasked(this.loginPage.passwordInput)).toBe(true);
});

When('the user toggles the password visibility', async function (this: ScenarioContext) {
  await this.loginPage.togglePasswordVisibility();
});

Then('the password should be shown in plain text', async function (this: ScenarioContext) {
  expect(await this.loginPage.isPasswordMasked(this.loginPage.passwordInput)).toBe(false);
});

Then('the password should be masked again', async function (this: ScenarioContext) {
  expect(await this.loginPage.isPasswordMasked(this.loginPage.passwordInput)).toBe(true);
});

// ==================== Forgot Password ====================

When('the user clicks "Forgot\\/Reset Password?"', async function (this: ScenarioContext) {
  await this.loginPage.clickForgotResetPassword();
});

Then('the Forgot Password screen should be displayed', async function (this: ScenarioContext) {
  expect(await this.loginPage.isForgotPasswordScreenDisplayed()).toBe(true);
});

When('the user requests a password reset code using the test data email', async function (this: ScenarioContext) {
  const email = this.testData.Email as string;
  await this.loginPage.submitForgotPassword(email);
});

Then('a reset-code confirmation should be displayed', async function (this: ScenarioContext) {
  await expect(this.loginPage.toastMessage.or(this.page.getByText(/code has been sent|check your email/i))).toBeVisible();
});

Then('no reset-code confirmation should be displayed', async function (this: ScenarioContext) {
  await expect(this.page.getByText(/code has been sent/i)).toHaveCount(0);
});

When('the user submits the Forgot Password form with the email left blank', async function (this: ScenarioContext) {
  await this.loginPage.forgotPasswordEmailInput.fill('');
  await this.loginPage.sendResetCodeButton.click();
});

When('the user submits the Forgot Password form with an invalid-format email', async function (this: ScenarioContext) {
  const invalidEmail = this.testData.InvalidEmail as string;
  await this.loginPage.submitForgotPassword(invalidEmail);
});

When('the user clicks "Back to Login"', async function (this: ScenarioContext) {
  await this.loginPage.clickBackToLogin();
});

Then('the user should be returned to the Login page', async function (this: ScenarioContext) {
  expect(await this.loginPage.isLoginPageDisplayed()).toBe(true);
});

Then('a mandatory-field indicator should be visible next to the Email field on the Forgot Password screen', async function (
  this: ScenarioContext,
) {
  await expect(this.loginPage.forgotPasswordMandatoryIndicator).toBeVisible();
});

// ==================== Authenticated Change Password ====================

Given('the user is logged in as a {string} user', async function (this: ScenarioContext, role: string) {
  const row = this.testData as Record<string, string>;
  const email = row.Email;
  const password = resolveRowPassword(row, 'PasswordKey');

  // Super Admin is currently blocked by the live backend's login rate limiter — skip
  // rather than fail. Do not remove without explicit confirmation it's unlocked again.
  if (role?.toLowerCase().includes('super admin') || email?.toLowerCase().includes('superadmin')) {
    return 'skipped';
  }

  const browser = getSharedBrowser();
  await this.context?.close();
  const authed = await getAuthenticatedPage(browser, email, password);
  this.context = authed.context;
  this.page = authed.page;
  this.testData.LoggedInRole = role;
});

When('the user navigates to Profile and selects "Change Password"', async function (this: ScenarioContext) {
  await this.loginPage.navigateToChangePassword();
});

Then('the authenticated Change Password screen should be displayed', async function (this: ScenarioContext) {
  expect(await this.loginPage.isChangePasswordScreenDisplayed()).toBe(true);
});

When('the user submits a password change using the test data current, new and confirm password', async function (
  this: ScenarioContext,
) {
  const row = this.testData as Record<string, string>;
  const current = resolveRowPassword(row, 'CurrentPasswordKey');
  const newPassword = row.NewPassword ?? resolveRowPassword(row, 'NewPasswordKey');
  const confirm = row.ConfirmPassword ?? newPassword;
  await this.loginPage.changePassword(current, newPassword, confirm);
});

When('the user submits a password change leaving the new password field blank', async function (this: ScenarioContext) {
  const current = resolveRowPassword(this.testData, 'CurrentPasswordKey');
  await this.loginPage.changePassword(current, '', '');
});

When('the user submits a password change with an incorrect current password', async function (this: ScenarioContext) {
  const row = this.testData as Record<string, string>;
  const newPassword = row.NewPassword as string;
  await this.loginPage.changePassword('WrongCurrentPass1!', newPassword, newPassword);
});

When('the user submits a password change leaving the current password field blank', async function (this: ScenarioContext) {
  const row = this.testData as Record<string, string>;
  const newPassword = row.NewPassword as string;
  await this.loginPage.changePassword('', newPassword, newPassword);
});

When('the user submits a password change with mismatched new and confirm password values', async function (this: ScenarioContext) {
  const row = this.testData as Record<string, string>;
  const current = resolveRowPassword(row, 'CurrentPasswordKey');
  await this.loginPage.changePassword(current, row.NewPassword, 'Different1234!');
});

When('the user submits a password change with a new password below the minimum length', async function (this: ScenarioContext) {
  const current = resolveRowPassword(this.testData, 'CurrentPasswordKey');
  await this.loginPage.changePassword(current, 'Pass01!', 'Pass01!');
});

Then('the password change should succeed with a confirmation message', async function (this: ScenarioContext) {
  await expect(this.loginPage.toastMessage.or(this.page.getByText(/password.*(changed|updated).*success/i))).toBeVisible();
});

Then('the password change should be blocked with a validation error', async function (this: ScenarioContext) {
  await expect(this.page.getByText(/required|incorrect|do not match|minimum|must/i)).toBeVisible();
});

// ==================== Session ====================

When('the user refreshes the browser', async function (this: ScenarioContext) {
  await this.page.reload();
});

Then('the user should remain authenticated on the protected page', async function (this: ScenarioContext) {
  await expect(this.page).not.toHaveURL(/\/login/);
});

When('the user logs out', async function (this: ScenarioContext) {
  await this.loginPage.logout();
});

When('the user navigates back using the browser Back button', async function (this: ScenarioContext) {
  await this.page.goBack();
});

Then('the user should be redirected to the Login page', async function (this: ScenarioContext) {
  await this.loginPage.assertRedirectedToLogin();
});

When('the user navigates directly to the dashboard URL', async function (this: ScenarioContext) {
  await this.page.goto(`${this.page.url().split('/').slice(0, 3).join('/')}/dashboard`);
});

