Given('the viewport is set to {int} by {int}', async function (this: ScenarioContext, width: number, height: number) {
  await this.page.setViewportSize({ width, height });
});

Then('the Login page fields and Sign In button should be visible without horizontal overflow', async function (this: ScenarioContext) {
  await expect(this.loginPage.emailInput).toBeVisible();
  await expect(this.loginPage.passwordInput).toBeVisible();
  await expect(this.loginPage.signInButton).toBeVisible();
  const hasOverflow = await this.page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth);
  expect(hasOverflow).toBe(false);
});

Then('the Login page should render and function consistently across Chrome, Firefox, Safari and Edge', async function (
  this: ScenarioContext,
) {
  // Cross-browser coverage is driven by Playwright's multi-project configuration
  // (Chromium/Firefox/WebKit + msedge channel), not by in-step browser switching.
  expect(await this.loginPage.isLoginPageDisplayed()).toBe(true);
});

When('the user presses Tab repeatedly from page load', async function (this: ScenarioContext) {
  for (let i = 0; i < 4; i++) {
    await this.page.keyboard.press('Tab');
  }
});

Then('focus should move through the Login page controls in a logical, keyboard-reachable order', async function (this: ScenarioContext) {
  const activeTag = await this.page.evaluate(() => document.activeElement?.tagName);
  expect(activeTag).toBeTruthy();
});

Then('a visible focus indicator should be rendered on the focused element', async function (this: ScenarioContext) {
  await this.page.keyboard.press('Tab');
  const outline = await this.page.evaluate(() => {
    const el = document.activeElement as HTMLElement | null;
    return el ? window.getComputedStyle(el).outlineStyle : 'none';
  });
  expect(outline).not.toBe('none');
});

Then('the page title should be descriptive', async function (this: ScenarioContext) {
  const title = await this.page.title();
  expect(title.length).toBeGreaterThan(0);
  expect(title.toLowerCase()).not.toBe('untitled');
});
